def choose_move(observation):
    w = int(observation.get("grid_width", 8) or 8)
    h = int(observation.get("grid_height", 8) or 8)
    sp = observation.get("self_position") or [0, 0]
    op = observation.get("opponent_position") or [w - 1, h - 1]
    sx, sy = int(sp[0]), int(sp[1])
    ox, oy = int(op[0]), int(op[1])

    obstacles = set()
    for p in observation.get("obstacles") or []:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            x, y = int(p[0]), int(p[1])
            if 0 <= x < w and 0 <= y < h:
                obstacles.add((x, y))

    resources = []
    for r in observation.get("resources") or []:
        if isinstance(r, (list, tuple)) and len(r) >= 2:
            x, y = int(r[0]), int(r[1])
            if 0 <= x < w and 0 <= y < h and (x, y) not in obstacles:
                resources.append((x, y))
    if not resources:
        return [0, 0]

    def cheby(ax, ay, bx, by):
        dx = ax - bx
        if dx < 0:
            dx = -dx
        dy = ay - by
        if dy < 0:
            dy = -dy
        return dx if dx > dy else dy

    moves = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nsx, nsy = sx + dx, sy + dy
            if nsx < 0 or nsx >= w or nsy < 0 or nsy >= h:
                continue
            if (nsx, nsy) in obstacles:
                nsx, nsy = sx, sy
                dx = 0
                dy = 0
            moves.append((dx, dy, nsx, nsy))
    if not moves:
        return [0, 0]

    best_move = (0, 0)
    best_val = -10**18
    for dx, dy, nsx, nsy in moves:
        if (nsx, nsy) in resources:
            val = 10**9
        else:
            val = -10**18
            for tx, ty in resources:
                ds = cheby(nsx, nsy, tx, ty)
                do = cheby(ox, oy, tx, ty)
                lead = do - ds
                score = lead * 1000 - ds
                if (tx, ty) == (sx, sy):
                    score -= 200
                if score > val:
                    val = score
        if val > best_val:
            best_val = val
            best_move = (dx, dy)
    return [int(best_move[0]), int(best_move[1])]
